import{_ as r,C as o,o as s,c as l,j as t,a,E as i,aA as p,w as d}from"./chunks/framework.Dl6YrsJv.js";const _=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":null}'),u={name:"api.md"},m={class:"jldocstring custom-block",open:""};function f(c,e,h,g,w,b){const n=o("Badge");return s(),l("div",null,[e[4]||(e[4]=t("h1",{id:"API-Reference",tabindex:"-1"},[a("API Reference "),t("a",{class:"header-anchor",href:"#API-Reference","aria-label":'Permalink to "API Reference {#API-Reference}"'},"​")],-1)),e[5]||(e[5]=t("h2",{id:"Sampling",tabindex:"-1"},[a("Sampling "),t("a",{class:"header-anchor",href:"#Sampling","aria-label":'Permalink to "Sampling {#Sampling}"'},"​")],-1)),t("details",m,[t("summary",null,[e[0]||(e[0]=t("a",{id:"WarmupHMC.adaptive_warmup_mcmc",href:"#WarmupHMC.adaptive_warmup_mcmc"},[t("span",{class:"jlbinding"},"WarmupHMC.adaptive_warmup_mcmc")],-1)),e[1]||(e[1]=a()),i(n,{type:"info",class:"jlObjectType jlFunction",text:"Function"})]),e[3]||(e[3]=p('<p>Adaptively</p><ul><li><p>learn a (currently only) linear transformation of the posterior that simplifies MCMC sampling,</p></li><li><p>learn a NUTS step size (using standard Dual Averaging), and</p></li><li><p>return samples from the posterior.</p></li></ul><p>The warm-up procedure is windowed and insipred by <a href="https://mc-stan.org/docs/reference-manual/mcmc.html#automatic-parameter-tuning" target="_blank" rel="noreferrer">Stan</a>&#39;s and <a href="https://github.com/pymc-devs/nutpie" target="_blank" rel="noreferrer">nutpie</a>&#39;s warm-up procedures, but differs in several important ways:</p><ul><li><p>We initialize using Pathfinder!</p></li><li><p>Our warm-up windows aim to reach a certain number of GRADIENT EVALUATIONS , instead of a certain number of MCMC transitions (Stan).</p></li></ul><p>We start with a (default) target of 1000 gradient evaluations, and double that target after each warm-up window.</p><ul><li><p>Instead of only using the posterior positions (Stan), we use the posterior POSITIONS AND GRADIENTS (like e.g. nutpie).</p></li><li><p>Instead of only using the MCMC/posterior positions and gradients (Stan and nutpie),</p></li></ul><p>we also store and use the INTERMEDIATE POSITIONS AND GRADIENTS, i.e. the ones that MCMC visits before returning the &quot;final&quot; new position. We store up to (a default of) 1000 intermediate positions and gradients. The stored intermediate positions get selected (pseudo-)randomly, and only get selected if the Hamiltonian error is small enough.</p><ul><li>Instead of only learning a single (linear) transformation and upating that one repeatedly, we learn several transformations in parallel and</li></ul><p>at the end of each warm-up window select the one that minimizes a loss function. Currently, we learn three different linear transformations: * Pathfinder&#39;s initial transformation, enriched by an updated additional diagonal scaling, * A standard diagonal &quot;mass matrix&quot;. * A novel, adaptive sequence of Householder transformations followed by diagonal scaling.</p><p>The loss function that gets used to select the used linear transformation tries to reward transformations which turn the transformed posterior into something that&#39;s close to a Normal distribution without correlation. For transformed positions p&#39; and gradients g&#39;, the loss function is <code>loss(p&#39;, g&#39;) = sum((std(p&#39;) * std(g&#39;)))</code>, which is zero for Normal distributions with zero correlations, independently of the sampled positions and gradients.</p><ul><li>Instead of running the warm-up for a fixed number of windows,</li></ul><p>we try to estimate when continuing warming up is harmful/useless and stop warming up then. To facilitate this, we * only ever adapt the stepsize until (a default of) 50 MCMC transitions have ocurred in the current warm-up window, * and try to predict cost (in terms of gradient evaluations) for finishing sampling with the current kernel vs. restarting warm-up with a new window. The way we do this prediction will probably be changed in the future.</p><p>By only ever having 50 stepsize adaptation MCMC transitions, we can start collecting posterior samples early.</p>',13)),i(n,{type:"info",class:"source-link",text:"source"},{default:d(()=>[...e[2]||(e[2]=[t("a",{href:"https://github.com/nsiccha/WarmupHMC.jl/blob/82a829913f26defbedbf666f40fd65ee67df79ce/src/adaptive_warmup_mcmc.jl#L46-L81",target:"_blank",rel:"noreferrer"},"source",-1)])]),_:1})])])}const v=r(u,[["render",f]]);export{_ as __pageData,v as default};
